<?php
require __DIR__ . '/config.php';
$incidents = $pdo->query('SELECT id,title,location_name,latitude,longitude FROM incidents WHERE latitude IS NOT NULL AND longitude IS NOT NULL ORDER BY created_at DESC')->fetchAll();
$history = $pdo->query('SELECT origin_name,destination_name,distance_km,duration_minutes,created_at FROM route_searches ORDER BY created_at DESC LIMIT 8')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Best Route | Disaster Response</title><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin=""></head><body>
