<main class="container"><section class="page-heading"><div><p class="eyebrow">ROUTE PLANNING</p><h1>Showing Best Route to Location</h1><p class="muted">Find a driving route between two places and view its distance and estimated duration.</p></div></section>
<div class="route-layout"><section class="panel route-controls"><h2>Plan a route</h2><p class="muted">Enter a place name or choose a saved incident.</p><form id="routeForm"><label>Starting location<input id="origin" name="origin" value="Tahrir Square, Cairo, Egypt" required></label><label>Destination<input id="destination" name="destination" value="Nasr City, Cairo, Egypt" required></label><label>Use incident as destination<select id="incidentDestination"><option value="">Enter destination manually</option><?php foreach($incidents as $i): ?><option value="<?= h(json_encode(['title'=>$i['title'],'location'=>$i['location_name'],'lat'=>(float)$i['latitude'],'lng'=>(float)$i['longitude']],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP|JSON_HEX_TAG)) ?>"><?= h('#'.$i['id'].' — '.$i['title'].' · '.$i['location_name']) ?></option><?php endforeach; ?></select></label><div class="form-actions"><button class="btn primary" id="routeButton" type="submit">Find best route</button><button class="btn secondary" id="swapButton" type="button">Swap locations</button></div></form><div id="routeMessage" class="notice hidden" role="status"></div><div id="routeResult" class="route-result hidden"><div><span>Distance</span><strong id="distanceValue">—</strong></div><div><span>Estimated drive</span><strong id="durationValue">—</strong></div></div><p class="footnote">Route calculation requires internet access for geocoding, OpenStreetMap map tiles, and the public OSRM demo routing service.</p></section><section class="panel map-panel"><div id="map" aria-label="Map showing the route"></div><div class="map-legend"><span><i class="origin-dot"></i> Start</span><span><i class="destination-dot"></i> Destination</span><span id="routeSaveStatus">Route searches will be saved to MySQL.</span></div></section></div>
<section class="panel history-panel"><div class="section-title"><div><p class="eyebrow">RECENT ACTIVITY</p><h2>Recent route searches</h2></div></div><?php if (!$history): ?><p class="muted">No route searches saved yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>From</th><th>To</th><th>Distance</th><th>Estimated time</th><th>Created</th></tr></thead><tbody><?php foreach($history as $r): ?><tr><td><?= h($r['origin_name']) ?></td><td><?= h($r['destination_name']) ?></td><td><?= number_format((float)$r['distance_km'],1) ?> km</td><td><?= number_format((float)$r['duration_minutes'],0) ?> min</td><td><?= h(date('M j, H:i',strtotime($r['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
